{
  "criteria": [
    {
      "id": "C1",
      "level": "Accomplished",
      "mark": 7,
      "evidence": [
        {
          "where": "Introduction",
          "quote": "A near-real-time relay to monitoring stations on the ground would allow marine and conservation scientists to more accurately predict and react to coral bleaching events."
        },
        {
          "where": "Introduction",
          "quote": "Thus, only one satellite is required."
        }
      ],
      "reasoning": "The mission purpose, Australian benefit, rationale, and single-spacecraft choice are explained. The report identifies conservation scientists as users but does not clearly name the spacecraft operator or define customer organisations. The mission rationale is relevant, though some claims and the mission concept would benefit from stronger sourcing and more specific operational detail."
    },
    {
      "id": "C2",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Launch",
          "quote": "The proposed satellite will thus use the Vega E rocket as a launch vehicle – launched from the Guiana Space Centre Spaceport."
        },
        {
          "where": "Orbit",
          "quote": "Specifically, an altitude of 600km requires a mean inclination of $ 87.7924^{\\circ} $ for the satellite to remain sun-synchronous."
        },
        {
          "where": "Ground Control & Communications",
          "quote": "An average contact duration of almost twenty minutes was achieved, in addition to the already frequent amount of passes."
        },
        {
          "where": "Mission Duration & EOL",
          "quote": "A span of five years is a sound estimate of the useful lifespan of the proposed satellite."
        },
        {
          "where": "Image 1",
          "quote": ""
        }
      ],
      "reasoning": "The report uses STK, includes orbit views and access results, and addresses launch, orbit, communications, duration, and disposal. However, the stated 87.79° inclination is not sun-synchronous at 600 km; a retrograde inclination near 97.8° is needed. The stated launch-site latitude is also wrong. Launch feasibility, sensor performance, communications capacity, and EOL lifetime are not adequately demonstrated, and no software files are provided."
    },
    {
      "id": "C3",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Conclusion",
          "quote": "A polar sun-synchronous orbit allows for consistent illumination of the oceans while maintaining a constant sun angle."
        },
        {
          "where": "Conclusion",
          "quote": "Thus, launch may need to be adjusted if the rocket is still not constructed by the proposed date."
        }
      ],
      "reasoning": "The conclusion summarises the chosen mission elements and recognises launch-vehicle uncertainty. It is relevant but largely restates the proposal, and its conclusions rely on the incorrect sun-synchronous orbit inclination and do not discuss the limitations of the analysis."
    },
    {
      "id": "C4",
      "level": "Adequate",
      "mark": 4,
      "evidence": [
        {
          "where": "Executive Summary",
          "quote": "This report outlines the intended designs and procedures involved in the construction of a Earth observation satellite"
        },
        {
          "where": "Launch",
          "quote": "To compare existing spaceflight mission plans, a wiki sorted directory – ‘Timeline of spaceflight’ – will be referred to throughout the report [6]."
        },
        {
          "where": "Mission Duration & EOL",
          "quote": "It acts like a regular sail, utilising a large surface area to ‘ and is suitable for low-earth orbit altitudes [10]."
        }
      ],
      "reasoning": "The report has a recognisable engineering structure, executive summary, figures, tables, and bibliography. Presentation is weakened by an unacceptable Wikipedia source, incomplete and inconsistent references, unnumbered or weakly captioned figures, awkward grammar, and a visibly incomplete EOL sentence. The overall structure remains readable."
    }
  ],
  "requirements": [
    {
      "id": "R1",
      "met": "yes",
      "where": "Introduction"
    },
    {
      "id": "R2",
